code_sketch:
strip = ->(s) { s.strip }
downcase = ->(s) { s.downcase }
slug = ->(s) { s.tr(' ', '-') }
normalize = strip >> downcase >> slug
normalize.call('  Hello World ')      # => "hello-world"
read_length = File.method(:read) >> :length.to_proc
read_length.call('notes.txt')

